    if (!element.isConnected) {
      continue;
    }

    const localName = element.localName.toLowerCase();
    if (DANGEROUS_ELEMENTS.has(localName) || isToolElement(element)) {
      warnings.push({
        code: 'removed-element',
        message: `已删除危险或工具专用节点 <${element.nodeName}>`,
