:root {
  color: #172033;
  background: #edf1f7;
  font-family: "Segoe UI", "Microsoft YaHei UI", "PingFang SC", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --accent: #2563eb;
  --accent-strong: #1d4ed8;
  --accent-soft: #eaf1ff;
  --border: #dce3ee;
  --border-strong: #cbd5e1;
  --surface: #ffffff;
  --surface-muted: #f7f9fc;
  --text: #172033;
  --text-muted: #68758c;
  --danger: #d63c52;
  --danger-soft: #fff1f3;
  --warning: #bd6a00;
  --warning-soft: #fff7e7;
  --success: #15803d;
  --success-soft: #edfdf3;
  --shadow: 0 10px 30px rgba(31, 45, 70, 0.08);
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  min-width: 320px;
  min-height: 100%;
  margin: 0;
}

body {
  min-height: 100vh;
  overflow: hidden;
}

button,
input,
select {
  font: inherit;
}

button {
  color: inherit;
}

button:focus-visible,
input:focus-visible,
select:focus-visible,
[role="button"]:focus-visible,
pre:focus-visible {
  outline: 3px solid rgba(37, 99, 235, 0.24);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background:
    radial-gradient(circle at 8% 0%, rgba(37, 99, 235, 0.11), transparent 25rem),
    linear-gradient(145deg, #f3f6fb 0%, #e9eef6 100%);
}

.app-header {
  height: 74px;
  flex: 0 0 74px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 0 22px;
  border-bottom: 1px solid rgba(203, 213, 225, 0.85);
  background: rgba(255, 255, 255, 0.86);
  backdrop-filter: blur(18px);
}

.brand {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 13px;
}

.brand__mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  color: #fff;
  border-radius: 13px;
  background: linear-gradient(145deg, #3b82f6, #1d4ed8);
  box-shadow: 0 8px 18px rgba(37, 99, 235, 0.25);
}

.brand h1 {
  margin: 0;
  font-size: 17px;
  line-height: 1.25;
  letter-spacing: -0.015em;
}

.brand p {
  margin: 4px 0 0;
  color: var(--text-muted);
  font-size: 12px;
}

.local-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
  padding: 8px 12px;
  color: #315172;
  font-size: 12px;
  font-weight: 700;
  border: 1px solid #d9e5f6;
  border-radius: 999px;
  background: #f3f8ff;
}

.local-badge__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 0 4px rgba(34, 197, 94, 0.12);
}

.workspace {
  min-height: 0;
  flex: 1;
  display: grid;
  grid-template-columns: 316px minmax(480px, 1fr) 340px;
  gap: 12px;
  padding: 12px;
}

.panel {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(210, 219, 232, 0.95);
  border-radius: 17px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.panel--left,
.panel--right {
  overflow-y: auto;
  overscroll-behavior: contain;
}

.panel--preview {
  overflow: hidden;
}

.panel__section {
  padding: 17px;
  border-bottom: 1px solid #e7ecf3;
}

.panel__section:last-child {
  border-bottom: 0;
}

.panel__section--grow {
  min-height: 0;
  display: flex;
  flex: 1;
  flex-direction: column;
}

.section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 14px;
}

.section-heading--compact {
  margin-bottom: 11px;
}

.section-heading h2,
.preview-toolbar h2 {
  margin: 2px 0 0;
  font-size: 15px;
  line-height: 1.25;
}

.eyebrow {
  margin: 0;
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.counter {
  min-width: 42px;
  padding: 4px 8px;
  color: #53647d;
  font-size: 11px;
  font-weight: 800;
  text-align: center;
  border-radius: 999px;
  background: #eef2f7;
}

.counter--warning {
  color: var(--warning);
  background: var(--warning-soft);
}

.dropzone {
  display: flex;
  min-height: 148px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 18px;
  color: #40516b;
  text-align: center;
  border: 1.5px dashed #a9bdd9;
  border-radius: 14px;
  background: linear-gradient(150deg, #f8fbff, #f2f6fc);
  cursor: pointer;
  transition: 150ms ease;
}

.dropzone:hover,
.dropzone--active {
  color: var(--accent-strong);
  border-color: var(--accent);
  background: var(--accent-soft);
  transform: translateY(-1px);
}

.dropzone--disabled {
  opacity: 0.58;
  cursor: not-allowed;
  transform: none;
}

.dropzone__icon {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  margin-bottom: 2px;
  color: var(--accent);
  border-radius: 13px;
  background: #fff;
  box-shadow: 0 5px 14px rgba(37, 99, 235, 0.12);
}

.dropzone strong {
  font-size: 13px;
}

.dropzone > span:last-child {
  max-width: 220px;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.55;
}

.switch-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-top: 13px;
  cursor: pointer;
}

.switch-row span {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.switch-row strong {
  font-size: 12px;
}

.switch-row small {
  color: var(--text-muted);
  font-size: 10px;
  line-height: 1.4;
}

.switch-row input {
  width: 38px;
  height: 21px;
  flex: 0 0 auto;
  appearance: none;
  position: relative;
  margin: 0;
  border-radius: 999px;
  background: #cbd5e1;
  cursor: pointer;
  transition: background 150ms ease;
}

.switch-row input::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 4px rgba(15, 23, 42, 0.2);
  transition: transform 150ms ease;
}

.switch-row input:checked {
  background: var(--accent);
}

.switch-row input:checked::after {
  transform: translateX(17px);
}

.search-field {
  height: 38px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  color: #7b879a;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface-muted);
}

.search-field:focus-within {
  color: var(--accent);
  border-color: #8bb2f5;
  background: #fff;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.08);
}

.search-field input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  background: transparent;
  font-size: 12px;
}

.search-field button,
.icon-button,
.feedback button {
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.search-field button {
  color: #8793a6;
}

.list-scroll {
  min-height: 0;
  flex: 1;
  margin: 10px -5px -5px;
  padding: 0 5px 5px;
  overflow-y: auto;
}

.icon-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.icon-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px;
  border: 1px solid #e2e8f1;
  border-radius: 11px;
  background: #fff;
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

.icon-row:focus-within,
.icon-row:hover {
  border-color: #b9cceb;
  box-shadow: 0 4px 12px rgba(38, 65, 105, 0.07);
}

.icon-row__mark {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  color: var(--accent);
  border-radius: 9px;
  background: var(--accent-soft);
}

.icon-row__body {
  min-width: 0;
  flex: 1;
}

.icon-row__id {
  width: 100%;
  padding: 0;
  color: #1e293b;
  font-size: 12px;
  font-weight: 800;
  border: 0;
  border-bottom: 1px solid transparent;
  outline: 0;
  background: transparent;
}

.icon-row__id:focus {
  border-color: var(--accent);
}

.icon-row__meta {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 4px;
  color: var(--text-muted);
  font-size: 9px;
}

.icon-row__meta > span:not(:last-child)::after {
  content: "·";
  margin-left: 7px;
  color: #c0c8d5;
}

.truncate {
  min-width: 0;
  max-width: 105px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.warning-count {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  color: var(--warning);
  font-weight: 700;
}

.icon-button {
  width: 32px;
  height: 32px;
  flex: 0 0 auto;
  color: #64748b;
  border-radius: 9px;
  transition: 120ms ease;
}

.icon-button:hover:not(:disabled) {
  color: var(--accent);
  background: var(--accent-soft);
}

.icon-button--danger:hover:not(:disabled) {
  color: var(--danger);
  background: var(--danger-soft);
}

.icon-button--solid {
  color: #fff;
  background: var(--accent);
}

.icon-button--solid:hover:not(:disabled) {
  color: #fff;
  background: var(--accent-strong);
}

button:disabled {
  opacity: 0.46;
  cursor: not-allowed;
}

.text-button {
  padding: 4px 7px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 700;
  border: 0;
  border-radius: 7px;
  background: transparent;
  cursor: pointer;
}

.text-button:hover:not(:disabled) {
  background: var(--accent-soft);
}

.text-button--danger {
  color: var(--danger);
}

.text-button--danger:hover:not(:disabled) {
  background: var(--danger-soft);
}

.panel-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.panel-empty--compact {
  min-height: 110px;
  margin: 0;
  padding: 16px;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.6;
}

.panel-empty p {
  margin: 0 0 3px;
}

.panel-empty span {
  color: #94a3b8;
}

.preview-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 14px 17px;
  border-bottom: 1px solid #e7ecf3;
  background: rgba(255, 255, 255, 0.9);
}

.toolbar-controls {
  display: flex;
  align-items: center;
  gap: 13px;
}

.zoom-control {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
}

.zoom-control input {
  width: 92px;
  accent-color: var(--accent);
}

.zoom-control output {
  width: 35px;
  color: #344257;
  text-align: right;
}

.segmented {
  display: inline-flex;
  padding: 3px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #f3f6fa;
}

.segmented button {
  height: 28px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0 9px;
  color: #64748b;
  font-size: 10px;
  font-weight: 700;
  border: 0;
  border-radius: 7px;
  background: transparent;
  cursor: pointer;
}

.segmented button.segmented__active {
  color: #25334a;
  background: #fff;
  box-shadow: 0 2px 7px rgba(39, 55, 78, 0.1);
}

.preview-options {
  display: flex;
  align-items: center;
  gap: 17px;
  padding: 10px 17px;
  color: #67748a;
  font-size: 10px;
  border-bottom: 1px solid #e7ecf3;
  background: #fafbfd;
}

.preview-options label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
}

.preview-options input {
  width: 14px;
  height: 14px;
  margin: 0;
  accent-color: var(--accent);
}

.preview-options__result {
  margin-left: auto;
  font-weight: 700;
}

.feedback {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 12px 14px 0;
  padding: 9px 11px;
  font-size: 11px;
  border: 1px solid transparent;
  border-radius: 10px;
}

.feedback span {
  min-width: 0;
  flex: 1;
}

.feedback--success {
  color: #166534;
  border-color: #bbf7d0;
  background: var(--success-soft);
}

.feedback--info {
  color: #1e4f91;
  border-color: #bfdbfe;
  background: #eff6ff;
}

.feedback--error {
  color: #9f1239;
  border-color: #fecdd3;
  background: var(--danger-soft);
}

.preview-content {
  min-height: 0;
  flex: 1;
  padding: 16px;
  overflow: auto;
  overscroll-behavior: contain;
}

.empty-state,
.loading-state {
  min-height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 36px;
  color: var(--text-muted);
  text-align: center;
}

.empty-state__icon {
  width: 66px;
  height: 66px;
  display: grid;
  place-items: center;
  margin-bottom: 6px;
  color: var(--accent);
  border-radius: 21px;
  background: linear-gradient(145deg, #edf4ff, #e4edfd);
}

.empty-state h3,
.loading-state strong {
  margin: 12px 0 5px;
  color: #243147;
  font-size: 16px;
}

.empty-state p,
.loading-state p {
  max-width: 390px;
  margin: 0 0 18px;
  font-size: 12px;
  line-height: 1.7;
}

.empty-state--small {
  min-height: 240px;
}

.empty-state--small h3 {
  margin-top: 10px;
}

.spinner {
  width: 35px;
  height: 35px;
  border: 3px solid #dbeafe;
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 750ms linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.button {
  min-height: 37px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 13px;
  font-size: 11px;
  font-weight: 800;
  border: 1px solid transparent;
  border-radius: 10px;
  cursor: pointer;
  transition: 130ms ease;
}

.button--primary {
  color: #fff;
  border-color: var(--accent);
  background: linear-gradient(145deg, #3b82f6, #2563eb);
  box-shadow: 0 6px 14px rgba(37, 99, 235, 0.19);
}

.button--primary:hover:not(:disabled) {
  border-color: var(--accent-strong);
  background: linear-gradient(145deg, #2f75eb, #1d4ed8);
  transform: translateY(-1px);
}

.button--secondary {
  color: #315172;
  border-color: #cfddef;
  background: #f7faff;
}

.button--secondary:hover:not(:disabled) {
  color: var(--accent-strong);
  border-color: #9dbcf0;
  background: var(--accent-soft);
}

.button--wide {
  width: 100%;
}

.icon-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(148px, 1fr));
  gap: 12px;
  align-content: start;
}

.icon-card {
  min-width: 0;
  overflow: hidden;
  border: 1px solid #dfe6f0;
  border-radius: 13px;
  background: #fff;
  box-shadow: 0 3px 10px rgba(38, 55, 84, 0.04);
  transition: 140ms ease;
}

.icon-card:hover {
  border-color: #b8cbea;
  box-shadow: 0 10px 22px rgba(38, 55, 84, 0.09);
  transform: translateY(-2px);
}

.icon-card__canvas {
  min-height: 112px;
  display: grid;
  place-items: center;
  position: relative;
  padding: 15px;
  background:
    linear-gradient(45deg, #f3f5f8 25%, transparent 25%) 0 0 / 14px 14px,
    linear-gradient(45deg, transparent 75%, #f3f5f8 75%) 0 0 / 14px 14px,
    linear-gradient(45deg, transparent 75%, #f3f5f8 75%) 7px -7px / 14px 14px,
    linear-gradient(45deg, #f3f5f8 25%, #fff 25%) 7px -7px / 14px 14px;
}

.icon-card__canvas--dark {
  background:
    linear-gradient(45deg, #2c3442 25%, transparent 25%) 0 0 / 14px 14px,
    linear-gradient(45deg, transparent 75%, #2c3442 75%) 0 0 / 14px 14px,
    linear-gradient(45deg, transparent 75%, #2c3442 75%) 7px -7px / 14px 14px,
    linear-gradient(45deg, #2c3442 25%, #202733 25%) 7px -7px / 14px 14px;
}

.svg-preview {
  display: block;
  max-width: 100%;
  object-fit: contain;
  transition: width 120ms ease, height 120ms ease;
}

.icon-card__warning {
  position: absolute;
  top: 8px;
  right: 8px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 3px 6px;
  color: #9a5800;
  font-size: 9px;
  font-weight: 800;
  border: 1px solid #f3d79d;
  border-radius: 999px;
  background: rgba(255, 249, 232, 0.95);
}

.icon-card__body {
  min-height: 43px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 9px 10px 4px;
}

.icon-card__body strong {
  min-width: 0;
  overflow: hidden;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.icon-card__body code {
  flex: 0 0 auto;
  color: #7b879a;
  font-family: "Cascadia Code", Consolas, monospace;
  font-size: 9px;
}

.icon-card__actions {
  display: flex;
  gap: 4px;
  padding: 4px 7px 8px;
}

.icon-card__actions button {
  min-width: 0;
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  height: 29px;
  color: #5d6b80;
  font-size: 9px;
  font-weight: 700;
  border: 1px solid #e2e8f1;
  border-radius: 7px;
  background: #f9fbfd;
  cursor: pointer;
}

.icon-card__actions button:hover {
  color: var(--accent);
  border-color: #b9cef0;
  background: var(--accent-soft);
}

.download-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 9px;
}

.copy-box {
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid #e7ecf3;
}

.copy-box > label {
  display: block;
  margin-bottom: 7px;
  color: #5c6a80;
  font-size: 10px;
  font-weight: 800;
}

.copy-box__controls {
  display: flex;
  gap: 7px;
}

.copy-box select {
  min-width: 0;
  height: 35px;
  flex: 1;
  padding: 0 30px 0 10px;
  color: #334155;
  font-size: 11px;
  border: 1px solid var(--border);
  border-radius: 9px;
  background-color: #f9fbfd;
}

.diagnostic-list {
  max-height: 265px;
  display: flex;
  flex-direction: column;
  gap: 7px;
  overflow-y: auto;
}

.diagnostic {
  display: flex;
  gap: 8px;
  padding: 9px;
  border: 1px solid transparent;
  border-radius: 9px;
}

.diagnostic > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.diagnostic > div {
  min-width: 0;
}

.diagnostic strong {
  display: block;
  overflow: hidden;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.diagnostic p {
  margin: 3px 0 0;
  font-size: 9px;
  line-height: 1.45;
}

.diagnostic--warning {
  color: #8f5607;
  border-color: #f3dfb7;
  background: var(--warning-soft);
}

.diagnostic--error {
  color: #a1253c;
  border-color: #f7ccd4;
  background: var(--danger-soft);
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin: 0;
}

.summary-grid > div {
  padding: 10px;
  border: 1px solid #e3e9f2;
  border-radius: 9px;
  background: #fafbfd;
}

.summary-grid dt {
  color: var(--text-muted);
  font-size: 9px;
}

