await page.getByRole('button', { name: '生成 Sprite' }).click();
await page.getByText(/Sprite 和 Manifest 已生成|Sprite 已生成/).waitFor({ timeout: 5000 });
await page.screenshot({ path: 'artifacts/acceptance.png', fullPage: true });
