  importedCounter: await page.locator('.counter').first().textContent(),
  errorVisible: await page.getByText('10-broken.svg', { exact: true }).isVisible(),
  feedback: await page.locator('.feedback').textContent(),
  cards: await page.locator('.icon-card').count(),
  consoleErrors,
};
console.log(JSON.stringify(result, null, 2));
await browser.close();
